/// <summary>
/// Privacy Notice 0.21 (D432), effective 26 November 2026: every approved paragraph, as the owner approved it, must appear
/// word for word. Sources: D351 location wording (#271, §2–§9), staff viewing an ID (#513, Q188, D413) and online status
/// (#525, D422). Curly quotes and apostrophes are compared as straight ones, the notice's own style.
/// </summary>
static class PrivacyNotice021Checks
{
    public static readonly string[] Approved =
    [
        "Home city and trips. We collect the home city and trip destinations you choose. Your home city is your registered location. Using device location or checking in to a trip does not change it. Home city changes are normally limited to once every 30 days; authorised staff can assist with genuine moves or corrections.",
        "Travel and check-in. Travel lets you choose whether to discover people at a future destination and whether people there can discover you, subject to the trip’s dates and visibility settings. When you check in, we use a device-location reading to confirm that you are in the destination’s Swoovr market. We retain the confirmation time, market and method, rather than the coordinates used for that check. The most recently checked-in active trip supplies your active location for discovery. When no checked-in trip remains active, your home city supplies that location again. Near me continues to use your device location.",
        "Near me. When you allow location access and open Near me, your device sends location readings to Swoovr while that feature is open. We do not collect background location for Near me. We use the readings to find eligible people nearby, apply your distance filters and determine whether you can start contact in the enabled Swoovr market where you are.",
        "We store only your latest Near me position, rounded to a grid of approximately 500 metres and encrypted. We stop using a reading two hours after it was taken. Expired readings are normally deleted within the following five minutes.",
        "Your nearby visibility. “Appear in nearby searches” and “Show my approximate distance” are separate settings, both off by default. Your stored location alone does not make you discoverable. We check your settings and the applicable mode, eligibility and safety rules whenever someone searches or opens a profile.",
        "You can browse Near me with “Appear in nearby searches” off. Your location is then used for your own nearby results, filters and contact eligibility, without making you discoverable through Near me or revealing a GPS distance band about you. Contacting another member identifies you to that recipient under the normal contact rules.",
        "Turning “Appear in nearby searches” off immediately removes you from subsequent nearby discovery results and deletes the stored reading. If you continue browsing Near me, your device can send a new reading, which is stored with nearby visibility still off. To stop sending and storing new Near me readings, use the stop-sharing control or disable location access in your device or browser settings.",
        "We also delete the stored Near me reading when you stop sharing, sign out of all sessions, your account is restricted or you delete your account. Previously derived Home City check records follow the retention periods below.",
        "Monthly Home City check. If you share device location, we derive a daily outcome recording whether you were within the area around your registered home city, away from it, or on a checked-in trip. The initial home vicinity is a 25 km radius around the home city’s geographical reference point. This outcome contains no coordinates or record of the places you visited. Daily outcomes are kept for up to 35 days.",
        "Approximately once every 30 days, we assess these outcomes to identify home cities that may be out of date. Days without readings are unknown. Days covered by an active checked-in trip are excluded. We skip the assessment when there is insufficient evidence.",
        "If the assessment suggests that an update may be useful, our support team receives a private item containing your home city, the assessment dates and day counts. It does not contain your coordinates or the places you visited. These observations do not establish where you lived or where you were throughout the month.",
        "Support may send you a friendly message suggesting that you update your home city if you have moved. The assessment does not change your home city, restrict your account or place a warning on it. We retain count-only assessment records for up to 12 months to manage repeat checks and avoid repeated contact.",
        "We use your chosen home city, trips and check-ins to provide relevant discovery and contact features. When you use Near me, we also use your device location to provide nearby results, distance filtering and contact eligibility. We use the limited daily Home City outcomes to help keep registered home cities relevant and to offer assistance where an update may be useful.",
        "“Show my approximate distance” is off by default. When you enable it, eligible members may see a distance band rather than an exact distance. You can see other members’ distance bands only while your own distance visibility is enabled.",
        "GPS distance bands require both members to have suitable recent readings and the applicable visibility settings enabled. The “Nearby” band, meaning within approximately 2 km, requires both readings to be no more than 15 minutes old and accurate to within 250 metres. When the necessary conditions are not met, the GPS distance is shown as unknown.",
        "Where a Home City distance band is available, it is labelled as a distance between registered home cities. It does not indicate either member’s current physical location. Travellers receive a GPS distance band only when the relevant conditions are met; a trip destination is not substituted for a current position.",
        "Other members do not receive your coordinates or exact calculated distance. We use rounded positions, distance bands, access controls and limits on searches and location updates to reduce the risk of location inference.",
        "When you choose destination visibility, eligible members there may see you in Explore and their visitors list, marked as visiting. Members in your home market can continue to see you under your normal visibility settings.",
        "Discovery and contact rules use your profile, settings, home city, trips and check-ins and, when you use Near me, your rounded device position. These rules do not use your orientation.",
        "The monthly Home City assessment determines whether to create a private Support item. A member of our team decides whether to contact you. The assessment itself does not change your account or apply a restriction.",
        "Our self-hosted support system also holds private Home City check items containing a member’s registered home city, assessment dates and day counts. Access is limited to authorised staff. These internal items are not displayed in the member’s Support list before Support chooses to contact them. Any message Support sends is available through the normal Support conversation.",
        "Near me readings are used for at most two hours after they were taken and are normally deleted within the following five minutes. The immediate deletion events described above can remove them sooner.",
        "Daily Home City check outcomes are kept for up to 35 days. Count-only assessment records are kept for up to 12 months. Home City check items in our support system are kept for six months after closure.",
        "These periods apply to the operational records described here. The notice’s existing provisions concerning backups, legal obligations and preservation of information continue to apply.",
        "You can use Home market without sharing device location. You can stop sharing through Swoovr or disable location access in your device or browser settings. You can independently change “Appear in nearby searches” and “Show my approximate distance”.",
        "Stopping location sharing prevents new location readings and daily outcomes from being collected. Previously derived Home City outcomes and assessment records remain subject to the retention periods above. Without sufficient observations, the monthly assessment is skipped.",
        "geolocation information: your chosen home city and trip destinations; one-time trip check-in readings and their confirmation outcomes; and, when you use Near me, device-location readings that may constitute precise geolocation. The latest Near me position is stored in rounded, encrypted form, used for up to two hours and normally deleted within the following five minutes. We also retain the limited daily Home City outcomes and count-only assessments described above",  // §9 sits inside the California list, so it ends with ";" not "."
        "precise geolocation, when you use device-location features",
        "Online status: if you enable the \"Show when I'm online\" setting, we collect and process your recent activity to determine whether you are online. Your online status is displayed only to eligible members who have also enabled this setting. We do not disclose your last activity time to other members. You can disable this setting at any time, which stops the collection of activity data for this purpose and removes your online status from other members' view.",
        "Other members see only the profile information your settings allow in each mode, your online status if the conditions described above are met, and the messages you send them.",
        "If the date of birth on your Swoovr account doesn't match your ID, or we can't confirm it from your ID check, a Swoovr administrator may view your ID check result and the images of your ID document held by Didit, to check your date of birth and complete your verification. The images are shown from Didit and we don't keep a copy. The administrator must record a reason, access is time-limited, and every view is logged.",
        "Except as described in the next paragraph, other staff see only that an identity is on file, when, and the issuing country.",
        "ID verification selfies and documents never go through this process; Didit holds them, and our staff view ID document images only as described under ID verification and your identity record.",
    ];

    public static void Run()
    {
        static string Plain(string t) => t.Replace('\u2019', '\'').Replace('\u2018', '\'').Replace('\u201C', '"').Replace('\u201D', '"');
        var all = string.Join("\n", Swoovr.Client.PrivacyNotice.Sections.SelectMany(s => s.Paragraphs));
        var missing = Approved.Select(Plain).Where(p => !all.Contains(p, StringComparison.Ordinal)).ToList();
        if (missing.Count > 0) throw new Exception("Privacy notice 0.21 wording not word for word: " + missing[0]);
        if (all.Contains("display name, area,") || all.Contains("one-time area checks") || all.Contains("When you confirm arrival or we check your home area"))
            throw new Exception("Privacy notice 0.21: superseded location wording remains");
        Console.WriteLine($"PASS: privacy notice 0.21 wording ({Approved.Length} approved paragraphs, word for word).");
    }
}
